def test_prepped_ds_error(reduced_cmod_test_dataset):
    """Test that assigning the wrong sample coordinate to the TrainingMetadata raises an error."""
    ds, _, _, _ = reduced_cmod_test_dataset

    data_var_names = list(ds.data_vars.keys())

    train_meta = TrainingMetadata(
        convert_xr_to_jnp=False,
        sample_coord=data_var_names[0], # Data vars are 2D, so this should create an error.
        sample_dim="shot",
        input_vars=data_var_names[:2],
        target_vars=data_var_names[2:4],
        time_dep_metadata=TrainingMetadata.TimeDepMetadata(
            state_init_vars=data_var_names[4:],
            time_coord="time",
            time_dim="time",
        )
    )


    with pytest.raises(ValueError):
        dataset = XarrayPreppedDataset(ds, train_meta)

@pytest.mark.parametrize("batch_size", [None, 1024, np.iinfo(np.int32).max])
@pytest.mark.parametrize("time_dependent", [True, False])
@pytest.mark.parametrize("segment_length", [None, 100])
def test_dl_limit_size_cmod(reduced_cmod_test_dataset, batch_size, time_dependent, segment_length):
    """Tests for limiting dimensions in the dataloader in a typical workflow"""
    ds, state_init_vars, input_vars, target_vars = reduced_cmod_test_dataset

    convert_xr = True
    shuffle = True

    if time_dependent:
        dl = make_time_dep_dataloader(
            ds=ds,
            time_coord="time",
            episode_coord="shot",
            state_init_vars=state_init_vars,
            input_vars=input_vars,
            target_vars=target_vars,
            batch_size=batch_size,
            convert_xr_to_jnp=convert_xr,
            segment_length=segment_length,
            shuffle=shuffle
        )
    else:
        dl = make_time_indep_dataloader(
            ds=ds,
            time_coord="time",
            episode_coord="shot",
            input_vars=input_vars,
            target_vars=target_vars,
            batch_size=batch_size,
            convert_xr_to_jnp=convert_xr,
            shuffle=shuffle
        )

    # Check that we can limit by the episode coord
    lim_dl = dl.limit_size(size=10, coord="shot")
    assert np.unique(lim_dl.ds.shot).size == 10

    if time_dependent:
        # If a short segment length is provided, there should be more samples than shots
        if segment_length and (segment_length <= lim_dl.ds.sizes["time_slice_input"]):
            assert lim_dl.ds.sizes["sample"] > 10

        # Check that we can limit by the time segment dimension
        lim_dl = dl.limit_size(size=10, coord="time_slice_input")
        assert np.unique(lim_dl.ds.time_slice_input).size == 10
    else:
        # Check that we can limit by the sample dimension
        lim_dl = dl.limit_size(size=10, coord="sample")
        assert np.unique(lim_dl.ds.sample).size == 10
        _run_dl_checks(lim_dl, batch_size=batch_size, expected_n_samps=10, shuffle=shuffle, segment_length=None, convert_xr=convert_xr)

@pytest.mark.parametrize("time_dependent", [True, False])
def test_dl_limit_size_constructed(time_dependent):
    """More rigorous testing of the limit_size method, covering limit by every coordinate and dimension"""
    num_shots = 4
    num_times = 30
    ds = xr.Dataset(
        {
            "p_rad": (("shot", "time_slice"), np.random.rand(num_shots, num_times)),
            "ip": (("shot", "time_slice"), np.random.rand(num_shots, num_times)),
            "n_e": (("shot", "time_slice"), np.random.rand(num_shots, num_times)),
            "Wmhd": (("shot", "time_slice"), np.random.rand(num_shots, num_times)),
        },
        coords={
            "shot": np.arange(num_shots),
            "time_slice": np.arange(num_times),
            "time": (("shot", "time_slice"), np.tile(np.arange(num_times)*0.001, (num_shots, 1))),
        }
    )
    state_init_vars = ["Wmhd"]
    target_vars = ["p_rad"]
    input_vars = ["ip", "n_e"]

    convert_xr = True
    shuffle = False
    segment_length = 10
    batch_size = None

    if time_dependent:
        dl = make_time_dep_dataloader(
            ds=ds,
            time_coord="time",
            episode_coord="shot",
            state_init_vars=state_init_vars,
            input_vars=input_vars,
            target_vars=target_vars,
            convert_xr_to_jnp=convert_xr,
            segment_length=segment_length,
            batch_size=batch_size,
            shuffle=shuffle
        )
    else:
        dl = make_time_indep_dataloader(
            ds=ds,
            time_coord="time",
            episode_coord="shot",
            input_vars=input_vars,
            target_vars=target_vars,
            convert_xr_to_jnp=convert_xr,
            shuffle=shuffle
        )

    for coord in list(dl.ds.coords) + list(dl.ds.dims):
        lim_dl = dl.limit_size(size=2, coord=coord)
        assert np.unique(lim_dl.ds[coord]).size == 2

def test_prng(reduced_cmod_test_dataset):
    ds, _, _, _ = reduced_cmod_test_dataset
    dl = make_time_indep_dataloader(
        ds=ds,
        time_coord="time",
        episode_coord="shot",
        input_vars=["p_rad", "ip", "n_e"],
        target_vars=["Wmhd"],
        convert_xr_to_jnp=True,
        batch_size=512,
        shuffle=True,
        generate_prng=True
    )
    
    # Check that when we grab the next batch, there is a "prng_key" variable in the dataset.
    batch = next(iter(dl))
    assert "prng_key" in batch.ds
    prng_key1 = dl.ds["prng_key"].data
    
    _ = next(iter(dl))
    prng_key2 = dl.ds["prng_key"].data
    
    # Check that the prng keys are different for different batches.
    assert not np.array_equal(prng_key1, prng_key2)

@pytest.mark.parametrize("method", ["drop_slice_all", "drop_slice_any", "drop_segment"])
def test_time_dep_dl_nan_handling_no_nan(method):
    """Test that the dataloader returns the same dataset when there are no NaNs to handle for all three NaN handling methods."""
    ds_orig = xr.Dataset(
        data_vars={
            "input_1": (("shot", "time_idx"), np.array([[1.0, 1.1, 1.2, 1.3], [1.0, 1.1, 1.2, 1.3]])),
            "input_2": (("shot", "time_idx"), np.array([[2.0, 2.1, 2.2, 2.3], [2.0, 2.1, 2.2, 2.3]])),
            "target_0D": (("shot", "time_idx"), np.array([[3.0, 3.1, 3.2, 3.3], [3.0, 3.1, 3.2, 3.3]])),
            "target_1D": (("shot", "time_idx", "rho"), np.array([[[4.00, 4.01, 4.02], [4.10, 4.11, 4.12], [4.20, 4.21, 4.22], [4.30, 4.31, 4.32]], [[4.00, 4.01, 4.02], [4.10, 4.11, 4.12], [4.20, 4.21, 4.22], [4.30, 4.31, 4.32]]])),

        },
        coords={
            "time": (("shot", "time_idx"), np.array([[0.0, 0.1, 0.2, 0.3], [0.0, 0.1, 0.2, 0.3]])),
            "shot": [1, 2],
            "rho": [0, 0.5, 1],
        },
    )

    ds_expected = xr.Dataset(
        data_vars={
            "input_1": (("sample", "time_idx_input"), np.array([[1.0, 1.1, 1.2, 1.3], [1.0, 1.1, 1.2, 1.3]])),
            "input_2": (("sample", "time_idx_input"), np.array([[2.0, 2.1, 2.2, 2.3], [2.0, 2.1, 2.2, 2.3]])),
            "target_0D": (("sample", "time_idx_input"), np.array([[3.0, 3.1, 3.2, 3.3], [3.0, 3.1, 3.2, 3.3]])),
            "target_1D": (("sample", "time_idx_input", "rho_input"), np.array([[[4.00, 4.01, 4.02], [4.10, 4.11, 4.12], [4.20, 4.21, 4.22], [4.30, 4.31, 4.32]], [[4.00, 4.01, 4.02], [4.10, 4.11, 4.12], [4.20, 4.21, 4.22], [4.30, 4.31, 4.32]]])),
        },
        coords={
            "time": (("sample", "time_idx_input"), np.array([[0.0, 0.1, 0.2, 0.3], [0.0, 0.1, 0.2, 0.3]])),
            "input_batch": ("sample", [0, 0]),
            "shot": ("sample", [1, 2]),
            "rho": (("rho_input"), np.array([0, 0.5, 1])),
        },
    )

    dl = make_time_dep_dataloader(
        ds=ds_orig,
        time_coord="time",
        episode_coord="shot",
        state_init_vars=[],
        input_vars=["input_1", "input_2"],
        target_vars=["target_0D", "target_1D"],
        convert_xr_to_jnp=False,
        batch_size=None,
        shuffle=False,
        nan_handling=method
    )

    # Check that the resulting dataloader dataset is the same as the original, since there are no NaNs to handle.
    for var in list(ds_expected.data_vars) + list(ds_expected.coords):
        assert np.allclose(dl.ds[var].data, ds_expected[var].data, atol=1e-06)


@pytest.mark.parametrize("method", ["drop_slice_all", "drop_slice_any", "drop_segment"])
def test_time_dep_dl_nan_handling_start_timeslice(method):
    """Test that the dataloader correctly handles NaNs at the start of a time slice for all three NaN handling methods.
    The NaN handling method shouldn't really do anything in this case since it's similar to the shift_time_to_not_nan"""
    ds_orig = xr.Dataset(
        data_vars={
            "input_1": (("shot", "time_idx"), np.array([[np.nan, 1.1, 1.2, 1.3], [1.0, 1.1, 1.2, 1.3]])),
            "input_2": (("shot", "time_idx"), np.array([[np.nan, 2.1, 2.2, 2.3], [2.0, 2.1, 2.2, 2.3]])),
            "target_0D": (("shot", "time_idx"), np.array([[np.nan, 3.1, 3.2, 3.3], [3.0, 3.1, 3.2, 3.3]])),
            "target_1D": (("shot", "time_idx", "rho"), np.array([[[np.nan, np.nan, np.nan], [4.10, 4.11, 4.12], [4.20, 4.21, 4.22], [4.30, 4.31, 4.32]], [[4.00, 4.01, 4.02], [4.10, 4.11, 4.12], [4.20, 4.21, 4.22], [4.30, 4.31, 4.32]]])),

        },
        coords={
            "time": (("shot", "time_idx"), np.array([[0.0, 0.1, 0.2, 0.3], [0.0, 0.1, 0.2, 0.3]])),
            "shot": [1, 2],
            "rho": [0, 0.5, 1],
        },
    )

    ds_expected = xr.Dataset(
        data_vars={
            "input_1": (("shot", "time_idx"), np.array([[1.1, 1.2, 1.3, 1.3], [1.0, 1.1, 1.2, 1.3]])),
            "input_2": (("shot", "time_idx"), np.array([[2.1, 2.2, 2.3, 2.3], [2.0, 2.1, 2.2, 2.3]])),
            "target_0D": (("shot", "time_idx"), np.array([[3.1, 3.2, 3.3, 3.3], [3.0, 3.1, 3.2, 3.3]])),
            "target_1D": (("shot", "time_idx", "rho"), np.array([[[4.10, 4.11, 4.12], [4.20, 4.21, 4.22], [4.30, 4.31, 4.32], [4.30, 4.31, 4.32]], [[4.00, 4.01, 4.02], [4.10, 4.11, 4.12], [4.20, 4.21, 4.22], [4.30, 4.31, 4.32]]])),

        },
        coords={
            "time": (("shot", "time_idx"), np.array([[0.1, 0.2, 0.3, 0.3], [0.0, 0.1, 0.2, 0.3]])),
            "shot": [1, 2],
            "rho": [0, 0.5, 1],
        },
    )

    dl = make_time_dep_dataloader(
        ds=ds_orig,
        time_coord="time",
        episode_coord="shot",
        state_init_vars=[],
        input_vars=["input_1", "input_2"],
        target_vars=["target_0D", "target_1D"],
        convert_xr_to_jnp=False,
        batch_size=None,
        shuffle=False,
        nan_handling=method
    )

    # Check that the resulting dataloader dataset matches the expected dataset for the given NaN handling method.
    for var in list(ds_expected.data_vars) + list(ds_expected.coords):
        assert np.allclose(dl.ds[var].data, ds_expected[var].data, equal_nan=True, atol=1e-06)


