def test_time_dep_dl_nan_handling_intermittent(method, expected):
    """Test that the dataloader correctly handles NaNs that are intermittent across time slices for all three NaN handling methods.
    
    drop_slice_all should raise a ValueError since the NaNs only appear in a single variable
    drop_slice_any should have time skips and samples that are shorter than original since they wind up the same length
    drop_segment should raise a ValueError since both episodes have NaNs
    """
    ds_orig = xr.Dataset(
        data_vars={
            "input_1": (("shot", "time_idx"), np.array([[1.0, np.nan, 1.2, 1.3], [1.0, 1.1, 1.2, 1.3]])),
            "input_2": (("shot", "time_idx"), np.array([[2.0, 2.1, 2.2, 2.3], [2.0, 2.1, 2.2, 2.3]])),
            "target_0D": (("shot", "time_idx"), np.array([[3.0, 3.1, 3.2, 3.3], [3.0, 3.1, 3.2, 3.3]])),
            "target_1D": (("shot", "time_idx", "rho"), np.array([[[4.00, 4.01, 4.02], [4.10, 4.11, 4.12], [4.20, 4.21, 4.22], [4.30, 4.31, 4.32]], [[4.00, 4.01, 4.02], [4.10, 4.11, 4.12], [4.20, np.nan, 4.22], [4.30, 4.31, 4.32]]])),

        },
        coords={
            "time": (("shot", "time_idx"), np.array([[0.0, 0.1, 0.2, 0.3], [0.0, 0.1, 0.2, 0.3]])),
            "shot": [1, 2],
            "rho": [0, 0.5, 1],
        },
    )

    if isinstance(expected, str) and expected == "value_error":
        with pytest.raises(ValueError):
            dl = make_time_dep_dataloader(
                ds=ds_orig,
                time_coord="time",
                episode_coord="shot",
                state_init_vars=[],
                input_vars=["input_1", "input_2"],
                target_vars=["target_0D", "target_1D"],
                convert_xr_to_jnp=False,
                batch_size=None,
                shuffle=False,
                nan_handling=method
            )
    else:
        dl = make_time_dep_dataloader(
            ds=ds_orig,
            time_coord="time",
            episode_coord="shot",
            state_init_vars=[],
            input_vars=["input_1", "input_2"],
            target_vars=["target_0D", "target_1D"],
            convert_xr_to_jnp=False,
            batch_size=None,
            shuffle=False,
            nan_handling=method
        )

        # Check that the resulting dataloader dataset matches the expected dataset for the given NaN handling method.
        for var in list(expected.data_vars) + list(expected.coords):
            assert np.allclose(dl.ds[var].data, expected[var].data, equal_nan=True, atol=1e-06)


@pytest.mark.parametrize("time_dep", [True, False])
def test_make_dataloaders_handles_list_arguments(time_dep: bool):
    """Verify make_dataloaders applies list-valued args to the matching dataset index."""
    ds_full = xr.Dataset(
        {
            "p_rad": (("shot", "time_slice"), np.random.rand(4, 6)),
            "ip": (("shot", "time_slice"), np.random.rand(4, 6)),
            "n_e": (("shot", "time_slice"), np.random.rand(4, 6)),
            "Wmhd": (("shot", "time_slice"), np.random.rand(4, 6)),
        },
        coords={
            "shot": np.arange(4),
            "time_slice": np.arange(6),
            "time": (("shot", "time_slice"), np.tile(np.arange(6) * 0.001, (4, 1))),
        },
    )

    datasets = [ds_full.isel(shot=slice(0, 2)), ds_full.isel(shot=slice(2, 4))]
    batch_sizes = [1, 2]
    shuffles = [False, True]
    nan_handling = ["drop_slice_all", "drop_slice_all"]

    if time_dep:
        segment_lengths = [3, None]
        segment_overlaps = [1, 0]

        dls = make_dataloaders(
            datasets=datasets,
            time_coord="time",
            episode_coord="shot",
            state_init_vars=["Wmhd"],
            input_vars=["ip", "n_e"],
            target_vars=["p_rad"],
            convert_xr_to_jnp=False,
            batch_size=batch_sizes,
            segment_length=segment_lengths,
            segment_overlap=segment_overlaps,
            shuffle=shuffles,
            nan_handling=nan_handling,
        )

        expected_dls = [
            make_time_dep_dataloader(
                ds=ds,
                time_coord="time",
                episode_coord="shot",
                state_init_vars=["Wmhd"],
                input_vars=["ip", "n_e"],
                target_vars=["p_rad"],
                convert_xr_to_jnp=False,
                batch_size=batch_size,
                segment_length=segment_length,
                segment_overlap=segment_overlap,
                shuffle=shuffle,
                nan_handling=nan_method,
            )
            for ds, batch_size, segment_length, segment_overlap, shuffle, nan_method in zip(
                datasets, batch_sizes, segment_lengths, segment_overlaps, shuffles, nan_handling, strict=False
            )
        ]

        with pytest.raises(ValueError):
            make_dataloaders(
                datasets=datasets,
                time_coord="time",
                episode_coord="shot",
                state_init_vars=["Wmhd"],
                input_vars=["ip", "n_e"],
                target_vars=["p_rad"],
                convert_xr_to_jnp=False,
                batch_size=[1],  # Incorrect length
                segment_length=segment_lengths,
                segment_overlap=segment_overlaps,
                shuffle=shuffles,
                nan_handling=nan_handling,
            )
    else:
        dls = make_dataloaders(
            datasets=datasets,
            time_coord="time",
            episode_coord="shot",
            input_vars=["ip", "n_e"],
            target_vars=["p_rad"],
            convert_xr_to_jnp=False,
            batch_size=batch_sizes,
            shuffle=shuffles,
        )

        expected_dls = [
            make_time_indep_dataloader(
                ds=ds,
                time_coord="time",
                episode_coord="shot",
                input_vars=["ip", "n_e"],
                target_vars=["p_rad"],
                convert_xr_to_jnp=False,
                batch_size=batch_size,
                shuffle=shuffle,
            )
            for ds, batch_size, shuffle, in zip(
                datasets, batch_sizes, shuffles, strict=False
            )
        ]

    assert len(dls) == len(expected_dls)
    for created_dl, expected_dl in zip(dls, expected_dls, strict=False):
        assert created_dl.batch_size == expected_dl.batch_size
        assert created_dl.shuffle == expected_dl.shuffle
        assert len(created_dl) == len(expected_dl)
        assert created_dl.ds.equals(expected_dl.ds)

        created_first_batch = next(iter(created_dl))
        expected_first_batch = next(iter(expected_dl))
        assert created_first_batch == expected_first_batch


